using System;
using System.Linq;
using NUnit.Framework;
using Unity.Collections;
using Unity.Netcode;
using UnityEditor;
using UnityEngine;
using DeadQuarantine.PvPvE;
using DeadQuarantine.PvPvE.Networking;
// Adapted useful previous audit cases to current records/assets/store; no mock connection booleans.
public class PvPvEIntegrationReviewTests {
 static PvPvENetworkSettings Settings=>AssetDatabase.LoadAssetAtPath<PvPvENetworkSettings>("Assets/PvPvE/Settings/PvPvENetworkSettings.asset");
 static void RoundTrip<T>(T expected)where T:unmanaged,INetworkSerializable,IEquatable<T>{using var writer=new FastBufferWriter(16384,Allocator.Temp);writer.WriteNetworkSerializable(expected);using var reader=new FastBufferReader(writer,Allocator.Temp);reader.ReadNetworkSerializable(out T actual);Assert.IsTrue(expected.Equals(actual),typeof(T).Name);}
 [Test] public void CurrentMemberPreservesIdentitySkinAndTeam(){RoundTrip(new PvPvEMember{ClientId=42,Name="Prueba Á",Team=PvPvETeam.Bravo,CharacterIndex=2});}
 [Test] public void CurrentReadinessPreservesAllFlagsAndTimeout(){RoundTrip(new PvPvEParticipant{ClientId=42,Flags=(PvPvEReadyFlags)15,Due=108.25});}
 [Test] public void CurrentStatsPreserveUtilityAndAllScoreColumns(){RoundTrip(new PvPvECombatStats{ClientId=42,Team=PvPvETeam.Bravo,Points=350,Kills=2,Deaths=1,Assists=3,StunnedUntil=100.5});}
 [Test] public void CurrentAmmoPreservesLifeWeaponAndReload(){RoundTrip(new PvPvEAmmo{ClientId=42,Life=13,Weapon=6,Magazine=2,Reserve=83,Reloading=true});}
 [Test] public void CurrentDeploymentPreservesRespawnAndPendingClass(){RoundTrip(new PvPvEDeployment{ClientId=42,ObjectId=78,Revision=13,Life=PvPvELifeStage.Dead,Acknowledged=false,Position=new(2,3,4),Rotation=Quaternion.Euler(0,40,0),Due=103.25,ProtectedUntil=104.75,ClassIndex=2,PendingIndex=4,Definition="{\"primary\":\"SemiRifle\"}"});}
 [Test] public void CurrentClassConfirmationPreservesEpochAndDefinition(){RoundTrip(new PvPvEConfirmedClass{ClientId=42,Epoch=8,ClassIndex=4,DefinitionJson="{\"name\":\"CLASE 5\"}"});}
 [Test] public void CurrentFeedPreservesCauseTeamsAndServerExpiry(){RoundTrip(new PvPvEKillEntry{Sequence=9,Killer=42,Victim=7,KillerName="Ana",VictimName="Leo",Weapon="Rifle semiautomático",KillerTeam=PvPvETeam.Bravo,VictimTeam=PvPvETeam.Alpha,Kind=PvPvEDamageKind.Bullet,Headshot=true,Expires=123.5});}
 [Test] public void CurrentRadarPreservesLifeAndExpiry(){RoundTrip(new PvPvERadarReveal{ClientId=42,ObjectId=78,Life=13,Until=104.25});}
 [Test] public void CurrentAssetsContainThreeCharactersThreeMapsAndCurrentModels(){var c=Settings;Assert.NotNull(c);Assert.AreEqual(3,Enumerable.Range(0,c.Characters.VariantCount).Select(i=>c.Characters.GetVariant(i).type).Distinct().Count());Assert.AreEqual(5,c.Characters.VariantCount);Assert.IsTrue(c.HasValidMaps);Assert.AreEqual(10,c.Capacity);Assert.AreEqual(50,c.KillLimit);Assert.AreEqual(600,c.MatchDurationSeconds);var presentation=c.PlayerPrefab.GetComponent<NetworkWeaponPresentation>();Assert.NotNull(presentation.Body);Assert.NotNull(presentation.BodyAnimator);foreach(var gun in c.Loadouts.weapons){var definition=presentation.Weapons.Single(w=>w.Id==gun.id);Assert.NotNull(definition.Source,gun.id);Assert.NotNull(definition.Model,gun.id);Assert.NotNull(definition.Controller,gun.id);Assert.NotNull(gun.icon,gun.id);Assert.Greater(gun.magazine,0,gun.id);}foreach(var map in c.Maps){Assert.NotNull(map.Preview);Assert.NotNull(map.Minimap);Assert.Greater(map.MinimapMax.x,map.MinimapMin.x);Assert.Greater(map.MinimapMax.y,map.MinimapMin.y);}Assert.NotNull(c.WalkerPrefab.GetComponent<ZombieAI>());Assert.NotNull(c.DogPrefab.GetComponent<ZombieAI>());}
 [Test] public void NonProtectedThirdPersonClipsUseHumanoidCreateFromThisModel(){var p=Settings.PlayerPrefab.GetComponent<NetworkWeaponPresentation>();var excluded=new[]{"Handgun","Rifle","Shotgun","Escopeta"};var paths=p.Weapons.Where(w=>!excluded.Contains(w.Id)).SelectMany(w=>w.Controller.animationClips).Select(AssetDatabase.GetAssetPath).Where(path=>path.EndsWith(".fbx",StringComparison.OrdinalIgnoreCase)&&System.IO.Path.GetFileName(path).StartsWith("A_TP_CH_",StringComparison.Ordinal)).Distinct().ToArray();Assert.Greater(paths.Length,0);foreach(var path in paths){var importer=(ModelImporter)AssetImporter.GetAtPath(path);Assert.AreEqual(ModelImporterAnimationType.Human,importer.animationType,path);Assert.AreEqual(ModelImporterAvatarSetup.CreateFromThisModel,importer.avatarSetup,path);}}
 [Test] public void BrokenSaveFallsBackWithoutOverwritingCorruptOriginal(){string profile="review-"+Guid.NewGuid().ToString("N"),key="DQ.PvPvE.Classes.v1."+profile;const string corrupt="{\"classes\":";try{PlayerPrefs.SetString(key,corrupt);var store=new PvPvEClassStore(Settings.Loadouts,profile);Assert.AreEqual(5,store.Count);for(int i=0;i<5;i++)Assert.IsTrue(Settings.Loadouts.Validate(store.Get(i),out _));Assert.AreEqual(corrupt,PlayerPrefs.GetString(key));}finally{PlayerPrefs.DeleteKey(key);PlayerPrefs.DeleteKey(key+".backup");PlayerPrefs.Save();}}
 [Test] public void BackupProfilesKeepStableClassIdsAfterPrimarySaveCorruption(){string profile="review-"+Guid.NewGuid().ToString("N"),key="DQ.PvPvE.Classes.v1."+profile;try{var store=new PvPvEClassStore(Settings.Loadouts,profile);var c=store.Get(2);c.name="RESPALDO QA";Assert.IsTrue(store.Save(2,c,out _));c.name="NUEVO QA";Assert.IsTrue(store.Save(2,c,out _));PlayerPrefs.SetString(key,"invalid");var restored=new PvPvEClassStore(Settings.Loadouts,profile);Assert.AreEqual("RESPALDO QA",restored.Get(2).name);Assert.AreEqual(c.primary,restored.Get(2).primary);}finally{PlayerPrefs.DeleteKey(key);PlayerPrefs.DeleteKey(key+".backup");PlayerPrefs.Save();}}
}
